fn gcd_calc(mut m: u32, mut n: u32) -> u32 {
    // Both m and n are assumed to be strictly positive.
    // We use the classic Euclidean algorithm:
    //   gcd(m, n) == gcd(n, m % n)
    // and terminate when n becomes zero, at which point m is the gcd.
    //
    // Invariants:
    //  1. m > 0 and n >= 0 at the start of each loop iteration.
    //  2. gcd(m, n) remains equal to the gcd of the original inputs.
    //  3. The measure (m + n) strictly decreases each iteration, guaranteeing termination.
    while n != 0 {
        let r = m % n;
        m = n;
        n = r;
    }
    m
}

